<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,reactive,ref} from 'vue'
import {api,APIError,body,type Row} from '../api'
import {randomID} from '../random'
import {confirmAction} from '../confirm'
import {toast} from '../toast'
import SelectField from './SelectField.vue'
import Icon from './Icon.vue'

const items=ref<Row[]>([]),loading=ref(true),ready=ref(false),busy=ref(false),error=ref(''),tab=ref('links'),query=ref(''),filter=ref('all'),conflict=ref(false),settingsConflict=ref(false),publicEnabled=ref(false)
const nameInput=ref<HTMLInputElement>(),formElement=ref<HTMLFormElement>()
const form=reactive({id:'',version:0,name:'',url:'',description:'',avatar_url:'',sort_order:0,visible:true})
const settings=reactive({enabled:true,title:'友链',description:'',version:0})
const initial=ref(''),settingsInitial=ref('');let createKey=randomID()
const fields=()=>({name:form.name,url:form.url,description:form.description,avatar_url:form.avatar_url,sort_order:Number(form.sort_order),visible:form.visible})
const settingsFields=()=>({enabled:settings.enabled,title:settings.title,description:settings.description})
initial.value=JSON.stringify(fields());settingsInitial.value=JSON.stringify(settingsFields())
const dirty=computed(()=>JSON.stringify(fields())!==initial.value),settingsDirty=computed(()=>JSON.stringify(settingsFields())!==settingsInitial.value)
const sorted=computed(()=>[...items.value].sort((a,b)=>a.sort_order-b.sort_order||Number(a.id)-Number(b.id)))
const filtered=computed(()=>sorted.value.filter(r=>(filter.value==='all'||r.visible===(filter.value==='visible'))&&(!query.value||[r.name,r.url,r.description].join(' ').toLocaleLowerCase().includes(query.value.toLocaleLowerCase()))))
const visibleCount=computed(()=>items.value.filter(r=>r.visible).length)
function safeURL(value:string){try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)&&!u.username&&!u.password?u.href:''}catch{return ''}}
function host(value:string){try{return new URL(value).host.replace(/^www\./,'')}catch{return '网站地址'}}
function imageState(event:Event){(event.target as HTMLImageElement).hidden=event.type==='error'}
function validRow(r:Row){return r&&typeof r.id==='string'&&/^\d+$/.test(r.id)&&Number.isSafeInteger(r.version)&&r.version>0&&['name','url','description','avatar_url'].every(k=>typeof r[k]==='string')&&typeof r.visible==='boolean'&&Number.isInteger(r.sort_order)}
function checkedList(data:Row){if(!Array.isArray(data.items)||!data.items.every(validRow))throw new Error('友链列表不完整，请重试。当前输入已保留。');return data.items as Row[]}
function applySettings(data:Row){if(typeof data.enabled!=='boolean'||typeof data.title!=='string'||typeof data.description!=='string'||!Number.isSafeInteger(data.version)||data.version<1)throw new Error('页面设置不完整，当前输入已保留。');Object.assign(settings,data);publicEnabled.value=data.enabled;settingsInitial.value=JSON.stringify(settingsFields());settingsConflict.value=false}
function fill(row?:Row){Object.assign(form,row?{id:row.id,version:row.version,...Object.fromEntries(Object.keys(fields()).map(k=>[k,row[k]]))}:{id:'',version:0,name:'',url:'',description:'',avatar_url:'',sort_order:Math.min(100000,Math.max(0,...items.value.map(r=>r.sort_order))+10),visible:true});initial.value=JSON.stringify(fields());createKey=randomID();conflict.value=false}
function message(e:unknown){return e instanceof Error?e.message:'操作失败，请稍后重试。'}
async function load(){if(busy.value)return;loading.value=true;error.value='';try{const [links,configuration]=await Promise.all([api('/studio/friends'),api('/studio/friend-settings')]);const checked=checkedList(links);applySettings(configuration);items.value=checked;fill();ready.value=true}catch(e){error.value=message(e)}finally{loading.value=false}}
async function edit(row?:Row){if(busy.value||!ready.value)return;if(dirty.value&&!await confirmAction('放弃未保存的友链修改？','切换前请先保存，或确认放弃当前输入。','放弃修改'))return;fill(row);error.value='';tab.value='links';await nextTick();formElement.value?.scrollIntoView({block:'nearest',behavior:'instant'});nameInput.value?.focus({preventScroll:true})}
async function save(){if(busy.value||conflict.value||!ready.value)return;busy.value=true;error.value='';try{const result=await api(form.id?'/studio/friends/'+form.id:'/studio/friends',{method:form.id?'PUT':'POST',...(form.id?{version:form.version}:{key:createKey}),body:body(fields())});if(!validRow(result))throw new Error('保存结果不完整，请刷新列表确认；当前输入已保留。');const index=items.value.findIndex(r=>r.id===result.id);if(index<0)items.value.push(result);else items.value[index]=result;fill(result);toast.success(result.visible?(publicEnabled.value?'友链已保存并展示。':'友链已保存，开启页面后会展示。'):'友链已保存，仅后台可见。')}catch(e){conflict.value=!!form.id&&e instanceof APIError&&e.status===409;if(conflict.value||(e instanceof APIError&&e.code==='VALIDATION_FAILED'))error.value=message(e);else toast.error(message(e))}finally{busy.value=false}}
async function latest(){if(busy.value||!form.id)return;if(dirty.value&&!await confirmAction('载入服务器最新友链？','当前输入将被服务器最新版本替换。','载入最新'))return;busy.value=true;error.value='';try{const rows=checkedList(await api('/studio/friends'));const selected=rows.find(r=>r.id===form.id);if(!selected)throw new Error('这条友链已删除，当前输入已保留。可以复制内容或另存为新友链。');items.value=rows;fill(selected);toast.success('已载入最新版本。')}catch(e){error.value=message(e);conflict.value=true}finally{busy.value=false}}
function saveAsNew(){form.id='';form.version=0;createKey=randomID();conflict.value=false;error.value='';toast.info('内容已保留，保存后创建一条新友链。')}
async function refreshList(){if(busy.value)return;busy.value=true;error.value='';try{items.value=checkedList(await api('/studio/friends'));toast.success('列表已刷新，当前编辑内容保留。')}catch(e){error.value=message(e)}finally{busy.value=false}}
async function remove(row:Row){if(busy.value)return;const local=form.id===row.id&&dirty.value;if(!await confirmAction('删除「'+row.name+'」？',local?'这条友链和当前未保存的修改都会移除，删除后无法恢复。':'公开页也会移除这条友链，删除后无法恢复。','删除友链'))return;busy.value=true;error.value='';try{await api('/studio/friends/'+row.id,{method:'DELETE',version:row.version});items.value=items.value.filter(r=>r.id!==row.id);if(form.id===row.id)fill();toast.success('友链已删除。')}catch(e){if(form.id===row.id&&e instanceof APIError&&e.status===409){conflict.value=true;error.value=message(e)}else toast.error(message(e))}finally{busy.value=false}}
async function saveSettings(){if(busy.value||settingsConflict.value||!ready.value)return;busy.value=true;error.value='';try{applySettings(await api('/studio/friend-settings',{method:'PUT',version:settings.version,body:body(settingsFields())}));toast.success(settings.enabled?'页面设置已保存。':'友链页面已关闭，入口也会隐藏，已有友链保留。')}catch(e){settingsConflict.value=e instanceof APIError&&e.status===409;if(settingsConflict.value||(e instanceof APIError&&e.code==='VALIDATION_FAILED'))error.value=message(e);else toast.error(message(e))}finally{busy.value=false}}
async function latestSettings(){if(busy.value)return;if(settingsDirty.value&&!await confirmAction('载入最新页面设置？','当前设置输入将被服务器最新版本替换。','载入最新'))return;busy.value=true;error.value='';try{applySettings(await api('/studio/friend-settings'));toast.success('已载入最新页面设置。')}catch(e){error.value=message(e)}finally{busy.value=false}}
function tabsKey(e:KeyboardEvent){const buttons=Array.from((e.currentTarget as HTMLElement).querySelectorAll<HTMLButtonElement>('[role=tab]'));let n=buttons.indexOf(e.target as HTMLButtonElement);if(e.key==='ArrowRight')n=(n+1)%buttons.length;else if(e.key==='ArrowLeft')n=(n+buttons.length-1)%buttons.length;else if(e.key==='Home')n=0;else if(e.key==='End')n=buttons.length-1;else return;e.preventDefault();buttons[n].click();buttons[n].focus()}
function beforeLeave(e:BeforeUnloadEvent){if(dirty.value||settingsDirty.value){e.preventDefault();e.returnValue=''}}
onMounted(()=>{void load();window.addEventListener('beforeunload',beforeLeave)})
onBeforeUnmount(()=>window.removeEventListener('beforeunload',beforeLeave))
</script>

<template>
 <section class="friend-manager">
  <div class="friends-manager-bar"><div class="settings-tabs" role="tablist" aria-label="友链管理分区" @keydown="tabsKey"><button id="friends-links-tab" role="tab" :tabindex="tab==='links'?0:-1" :aria-selected="tab==='links'" aria-controls="friends-links-panel" @click="tab='links'">友链列表</button><button id="friends-settings-tab" role="tab" :tabindex="tab==='settings'?0:-1" :aria-selected="tab==='settings'" aria-controls="friends-settings-panel" @click="tab='settings'">页面设置</button></div><a v-if="ready&&publicEnabled" class="button quiet" href="/friends" target="_blank" rel="noopener">查看友链页<Icon name="arrow" :size="16"/></a></div>
  <div v-if="error" class="notice error" role="alert">{{error}}<div class="friends-error-actions"><template v-if="conflict&&tab==='links'"><button :disabled="busy" @click="latest">载入最新版本</button><button :disabled="busy" @click="saveAsNew">另存为新友链</button></template><button v-else-if="settingsConflict" :disabled="busy" @click="latestSettings">载入最新设置</button><button v-else :disabled="busy||loading" @click="ready?refreshList():load()">重试读取</button></div></div>

  <p v-if="loading" role="status" class="muted">正在加载友链与页面设置…</p>
  <div id="friends-links-panel" v-show="tab==='links'" role="tabpanel" aria-labelledby="friends-links-tab" class="friends-workspace">
   <section class="friends-library" aria-label="已保存的友链">
    <div class="friends-library-heading"><p v-if="ready">{{visibleCount}} 个展示<span aria-hidden="true"> · </span>{{items.length-visibleCount}} 个隐藏</p><p v-else>已保存的友链</p><button class="primary" :disabled="busy||!ready" @click="edit()">添加友链</button></div>
    <div class="friends-library-filter"><label class="sr-only" for="friend-search">筛选友链</label><input id="friend-search" v-model="query" type="search" placeholder="搜索名称、网址或简介" :disabled="!ready"><SelectField v-model="filter" label="展示状态" :options="[{value:'all',label:'全部友链'},{value:'visible',label:'展示中'},{value:'hidden',label:'已隐藏'}]" :disabled="!ready"/></div>
    <div v-for="row in filtered" :key="row.id" class="friends-library-row" :class="{'is-editing':form.id===row.id}">
     <span class="friend-avatar" aria-hidden="true"><span>{{Array.from(row.name)[0]||'?'}}</span><img v-if="row.avatar_url" :src="row.avatar_url" width="48" height="48" loading="lazy" referrerpolicy="no-referrer" alt="" @error="imageState" @load="imageState"></span>
     <div class="friends-row-content"><div class="friends-row-heading"><h2>{{row.name}}</h2><span class="status" :class="{published:row.visible}">{{row.visible?'展示中':'已隐藏'}}</span></div><a :href="row.url" target="_blank" rel="noopener noreferrer" class="friends-row-url">{{host(row.url)}}<Icon name="arrow" :size="13"/></a><p v-if="row.description">{{row.description}}</p><div class="friends-row-bottom"><span>排序 {{row.sort_order}}</span><div><button class="quiet" :disabled="busy" :aria-label="'编辑 '+row.name" @click="edit(row)">{{form.id===row.id?'正在编辑':'编辑'}}</button><button class="quiet danger" :disabled="busy" :aria-label="'删除 '+row.name" @click="remove(row)">删除</button></div></div></div>
    </div>
    <div v-if="ready&&!filtered.length" class="friends-library-empty"><h2>{{items.length?'没有匹配的友链':'第一位朋友，从这里开始'}}</h2><p>{{items.length?'试试其他关键词或展示状态。':'填写网站名称和网址，就能为一个站点留出位置。'}}</p><button v-if="items.length" class="quiet" @click="query='';filter='all'">清除筛选</button></div>
   </section>
   <form ref="formElement" class="friends-composer" aria-label="友链编辑" @submit.prevent="save">
    <div class="friends-composer-title"><h2>{{form.id?'编辑友链':'添加友链'}}</h2><span v-if="dirty" class="friends-unsaved" role="status">未保存</span></div>
    <fieldset :disabled="busy||!ready"><label for="friend-name">网站名称<input id="friend-name" ref="nameInput" v-model="form.name" required maxlength="80" placeholder="怎么称呼这个站点"></label><label for="friend-url">网站地址<input id="friend-url" v-model="form.url" type="url" required maxlength="2048" placeholder="https://example.com" spellcheck="false" autocomplete="off"></label><label for="friend-description"><span>简介 <small>选填</small></span><textarea id="friend-description" v-model="form.description" rows="3" maxlength="240" placeholder="一两句话，介绍这里有什么。"></textarea></label><label for="friend-avatar"><span>头像地址 <small>选填</small></span><input id="friend-avatar" v-model="form.avatar_url" type="url" maxlength="2048" placeholder="https://example.com/avatar.png" spellcheck="false" autocomplete="off"><small>留空时使用名称首字，图片失效也有默认头像。</small></label><label for="friend-order">排序<input id="friend-order" v-model.number="form.sort_order" type="number" min="-100000" max="100000" step="1" required><small>数字越小越靠前，相同数字按添加先后排列。</small></label><label class="check"><input v-model="form.visible" type="checkbox">在友链页展示</label>
    <div class="friends-preview" aria-label="友链展示预览"><span class="friend-avatar" aria-hidden="true"><span>{{Array.from(form.name)[0]||'友'}}</span><img v-if="safeURL(form.avatar_url)" :src="safeURL(form.avatar_url)" width="48" height="48" referrerpolicy="no-referrer" alt="" @error="imageState" @load="imageState"></span><div><strong>{{form.name||'网站名称'}}</strong><span>{{host(form.url)}}</span></div></div>
    <div class="form-actions"><button class="primary" :disabled="busy||conflict||!ready||!form.name.trim()||!safeURL(form.url)">{{busy?'正在处理…':form.id?'保存修改':'添加友链'}}</button><button v-if="dirty" type="button" class="quiet" :disabled="busy" @click="edit(form.id?items.find(r=>r.id===form.id):undefined)">取消修改</button></div></fieldset>
   </form>
  </div>
  <div id="friends-settings-panel" v-show="tab==='settings'" role="tabpanel" aria-labelledby="friends-settings-tab" class="friends-settings-layout">
   <form class="friends-page-settings" aria-label="友链页面设置" @submit.prevent="saveSettings"><h2>页面设置</h2><p class="muted">决定读者看到什么，以及什么时候开放这扇门。</p><fieldset :disabled="busy||!ready"><label class="check friends-page-switch"><input v-model="settings.enabled" type="checkbox">开启友链页面</label><p class="friends-setting-help">关闭后，公开页面与页脚入口一同隐藏；已添加的友链仍会保留。</p><label for="friends-page-title">页面标题<input id="friends-page-title" v-model="settings.title" required maxlength="80" placeholder="友链"></label><label for="friends-page-description"><span>页面介绍 <small>选填</small></span><textarea id="friends-page-description" v-model="settings.description" rows="4" maxlength="400" placeholder="写一点你想对来访者说的话。"></textarea><small>纯文字，支持换行。留空时显示默认介绍。</small></label><div class="form-actions"><button class="primary" :disabled="busy||!ready||settingsConflict||!settings.title.trim()">{{busy?'正在处理…':'保存页面设置'}}</button><span v-if="settingsDirty" class="friends-unsaved" role="status">有未保存的设置</span></div></fieldset></form>
   <aside class="friends-settings-notes"><h2>和站点保持一致</h2><p>使用网站自己的头像与简介。留白、文字和真实内容，让每一个链接都容易辨认。</p><p>友链入口位于首页末尾和关于页。顶部导航和页脚继续保持简洁。</p><a v-if="ready&&publicEnabled" class="text-link" href="/friends" target="_blank" rel="noopener">查看公开效果<Icon name="arrow" :size="16"/></a></aside>
  </div>
 </section>
</template>

<style scoped>
.friends-manager-bar{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:28px;flex-wrap:wrap}.friends-manager-bar .settings-tabs{display:flex;margin:0}.friends-manager-bar>.button{font-size:.8rem}.friends-error-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.friends-workspace{display:grid;grid-template-columns:minmax(0,1fr) minmax(280px,340px);gap:36px;align-items:start}.friends-library{min-width:0}.friends-library-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:24px}.friends-library-heading p{color:var(--muted);font-size:.8rem;margin:0}.friends-library-filter{display:grid;grid-template-columns:minmax(0,1fr) 140px;gap:12px;align-items:end;margin-bottom:24px}.friends-library-filter:deep(.select-field){min-width:0}.friends-library-row{display:flex;gap:16px;padding:24px 0;border-top:1px solid var(--line);min-width:0}.friends-library-row.is-editing .friends-row-heading h2{color:var(--accent)}.friends-library-row .friend-avatar{width:44px;height:44px;border-radius:var(--radius-surface)}.friends-row-content{flex:1;min-width:0}.friends-row-heading{display:flex;align-items:center;gap:8px 14px;justify-content:space-between;flex-wrap:wrap}.friends-row-heading h2{font:600 1rem/1.7 var(--font-ui);margin:0;overflow-wrap:anywhere;min-width:0}.friends-row-heading .status{flex:none;font-size:.65rem}.friends-row-url{display:inline-flex;align-items:center;gap:8px;min-height:44px;color:var(--muted);font-size:.72rem;overflow-wrap:anywhere;max-width:100%}.friends-row-content>p{margin:8px 0;color:var(--muted);font-size:.8rem;line-height:1.8;white-space:pre-line;overflow-wrap:anywhere}.friends-row-bottom{display:flex;align-items:center;justify-content:space-between;gap:12px}.friends-row-bottom>span{font-size:.7rem;color:var(--muted);font-variant-numeric:tabular-nums}.friends-row-bottom>div{display:flex;gap:4px}.friends-row-bottom button{font-size:.75rem;padding:8px 10px}.friends-composer{background:var(--paper);border:1px solid var(--line);border-radius:var(--radius-surface);padding:24px;position:sticky;top:24px;min-width:0;max-height:calc(100dvh - 48px);overflow:auto;scroll-margin-top:90px}.friends-composer-title{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:24px}.friends-composer-title h2,.friends-page-settings h2{font:600 1.15rem/1.6 var(--font-ui);margin:0}.friends-unsaved{font-size:.72rem;color:var(--muted)}.friend-manager fieldset{border:0;margin:0;padding:0;min-width:0;display:grid;gap:20px}.friend-manager label{min-width:0}.friend-manager label small{font-weight:400;font-size:.72rem;line-height:1.8}.friend-manager label>span.muted{display:inline;font-size:.72rem;font-weight:400}.friend-manager .form-actions{margin-top:4px;flex-wrap:wrap;gap:8px}.friends-preview{display:flex;align-items:center;gap:14px;padding:20px 0 0;border-top:1px solid var(--line);min-width:0}.friends-preview .friend-avatar{width:44px;height:44px;border-radius:var(--radius-surface)}.friends-preview>div{min-width:0;display:grid;gap:4px;overflow-wrap:anywhere}.friends-preview strong{font-size:.86rem;font-weight:600}.friends-preview>div>span{font-size:.7rem;color:var(--muted)}.friends-library-empty{padding:40px 0;border-top:1px solid var(--line)}.friends-library-empty h2{font:500 1.4rem/1.6 var(--font-display);margin:0 0 12px}.friends-library-empty p{font-size:.86rem;color:var(--muted);margin:0}.friends-settings-layout{display:grid;grid-template-columns:minmax(0,640px) minmax(200px,280px);gap:64px;align-items:start}.friends-page-settings{background:var(--paper);border:1px solid var(--line);border-radius:var(--radius-surface);padding:28px;min-width:0}.friends-page-settings>p{font-size:.85rem;line-height:1.85;margin:12px 0 28px}.friends-page-switch{color:var(--ink)}.friends-setting-help{font-size:.78rem;line-height:1.85;color:var(--muted);margin:-12px 0 8px}.friends-settings-notes{padding-top:4px;min-width:0}.friends-settings-notes h2{font:500 1.35rem/1.6 var(--font-display);margin:0 0 20px}.friends-settings-notes p{color:var(--muted);font-size:.84rem;line-height:1.95;margin:0 0 20px}.friends-settings-notes .text-link{display:inline-flex;align-items:center;gap:8px;min-height:44px;font-size:.8rem}
@media(max-width:1250px){.friends-workspace{grid-template-columns:minmax(0,1fr) minmax(260px,310px);gap:24px}.friends-composer{padding:20px}.friends-settings-layout{gap:32px;grid-template-columns:minmax(0,1fr) 220px}.friends-library-filter{grid-template-columns:minmax(0,1fr)}.friends-library-filter:deep(.select-field){max-width:180px}}
@media(max-width:760px){.friends-workspace{grid-template-columns:minmax(0,1fr);gap:32px}.friends-composer{position:static;max-height:none;grid-row:1;padding:20px}.friends-library{grid-row:2}.friends-settings-layout{grid-template-columns:minmax(0,1fr);gap:32px}.friends-page-settings{padding:20px}.friends-manager-bar{gap:12px;margin-bottom:24px}.friends-manager-bar .settings-tabs{flex:1}.friends-manager-bar>.button{padding:8px 0}.friends-library-filter{grid-template-columns:minmax(0,1fr)}.friends-row-heading{gap:6px 10px}.friends-row-bottom{align-items:flex-start;flex-wrap:wrap}.friends-library-row{gap:12px}.friends-manager-bar .settings-tabs button{padding:10px 8px;line-height:var(--control-leading)}.friends-settings-notes{padding:0 4px}}
</style>
